    n = len(inputs["item_lengths"])
    for i in range(n):
        personal_ok = float(inputs["item_lengths"][i]) <= float(inputs["personal_item_limits"][0]) and float(inputs["item_widths"][i]) <= float(inputs["personal_item_limits"][1]) and float(inputs["item_heights"][i]) <= float(inputs["personal_item_limits"][2])
        carry_ok = float(inputs["item_lengths"][i]) <= float(inputs["carry_on_limits"][0]) and float(inputs["item_widths"][i]) <= float(inputs["carry_on_limits"][1]) and float(inputs["item_heights"][i]) <= float(inputs["carry_on_limits"][2])
        if personal_ok and not personal_used:
            personal_used = True
        elif carry_ok and not carry_used:
            carry_used = True
        else:
            checked = checked + [i]
    total = int(inputs["ticket_price"])
    for j in range(len(checked)):
        i = checked[j]
        base_fee = int(inputs["checked_base_fees"][j])
        weight = float(inputs["item_weights"][i])
        overweight = 0
        if weight > float(inputs["standard_checked_weight_limit"]):
            for k in range(len(inputs["overweight_upper_limits"])):
                if overweight == 0 and weight <= float(inputs["overweight_upper_limits"][k]):
                    overweight = int(inputs["overweight_fees"][k])
        size = float(inputs["item_lengths"][i]) + float(inputs["item_widths"][i]) + float(inputs["item_heights"][i])
        oversize = 0
        if size > float(inputs["standard_checked_size_limit"]):
            for k in range(len(inputs["oversize_upper_limits"])):
                if oversize == 0 and size <= float(inputs["oversize_upper_limits"][k]):
                    oversize = int(inputs["oversize_fees"][k])
        total = total + base_fee + max(overweight, oversize)
    return {"answer": total}

